{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can state the operational definition of current and of potential difference, explain why they are distinct quantities, and use conservation of charge and of energy to justify the junction and loop rules on a fresh circuit you have not seen before."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I confuse current with potential difference and cannot explain why circuit rules hold. Prepare for independent problem solving.",
          "explanation": "No assessment, deadline, or completion history is supplied, so the priority is the conceptual gap the learner named: current versus potential difference. The smallest useful path is one integrated study-and-application activity that (a) builds the two operational definitions and their distinction, (b) derives the junction rule from conservation of charge and the loop rule from conservation of energy, and (c) applies both to a fresh circuit. Because the learner reports confusion rather than demonstrated failure, no separate remediation set or second check is booked; a single independent fresh-circuit task is the honest evidence of readiness. Circuit problem solving is included as the application surface of the same activity, not as a separate method-selection course, since no taught repertoire or assessment method list was supplied.",
          "recommendedEffort": {
            "lowMinutes": 60,
            "likelyMinutes": 90,
            "highMinutes": 120
          },
          "phases": [
            {
              "localId": "phase_concept",
              "title": "Conceptual foundation and circuit-rule justification",
              "outcome": "You can distinguish current from potential difference and derive the junction and loop rules from conservation principles.",
              "effort": {
                "lowMinutes": 60,
                "likelyMinutes": 90,
                "highMinutes": 120
              },
              "readinessCriterion": "You correctly define both quantities, state their units and roles, and justify the two circuit rules by conservation on a fresh circuit."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Core conceptual target: operational definitions of current and potential difference and the reason they are distinct."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Provides the conservation-of-charge and conservation-of-energy justifications for the junction and loop rules."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Application surface: using the rules on a fresh circuit to demonstrate independent problem solving."
          }
        ],
        "activities": [
          {
            "localId": "concept_rules_apply",
            "outcomeRefs": [
              "phase_concept"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3"
            ],
            "title": "Current vs potential difference, conservation rules, and a fresh circuit",
            "activityType": "Integrated conceptual study and applied problem solving",
            "purpose": "Build the two operational definitions, derive the junction and loop rules from conservation, and apply them once on an unseen circuit as readiness evidence.",
            "instructions": "Work through this in one or two sittings. (1) Write an operational definition of electric current: what flows, in what direction convention, its unit, and what it measures about charge motion. (2) Write an operational definition of potential difference: what it measures, its unit, and why it is an energy-per-charge quantity rather than a flow quantity. (3) State in two or three sentences why a wire can carry a large current with a tiny potential difference across it, and why a component can have a large potential difference across it with no current through it. (4) Derive the junction rule from conservation of charge: argue that charge cannot accumulate at a junction in steady state, so the sum of currents in equals the sum out. (5) Derive the loop rule from conservation of energy: argue that the net work per unit charge around a closed loop is zero. (6) Draw a fresh circuit you have not analyzed before with at least one junction and two loops, assign currents and potential differences, and use both rules to find the unknown quantities. Show the rule you used at each step. If you have no circuit source, construct your own with two resistors in parallel fed by one series resistor from a battery. Do not use any method beyond the definitions and the two conservation rules unless you have already been taught it.",
            "completionCriterion": "You produce correct written definitions of current and potential difference with units; a correct conservation-based justification of both circuit rules; and a correct solution of your fresh circuit in which every step cites the junction or loop rule. A single clean attempt counts; no error log is required.",
