providerResponses.text:
{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "By the end of 2026-10-09 you can solve teacher-style circuit questions on current/voltage, series, parallel and mixed circuits, and you have an honest written list of what you could not yet do."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "My teacher-written circuit quiz is in two days. I need a defensible short plan; explicitly explain anything sacrificed. There are no verified topic weights.",
          "explanation": "Only 2026-10-08 and 2026-10-09 are available (25 minutes each, 50 minutes total); 2026-10-10 is the quiz itself and has zero study capacity and no exam-day study. With no verified topic weights and no recorded history, I treat current/voltage as the prerequisite core and series/parallel as the two highest-yield circuit patterns, then integrate mixed circuits as a short extension rather than a separate unit. I deliberately do not book a separate diagnostic, a separate method-selection lesson, or a second full check: one integrated teach-and-solve activity plus one changed-example application check is the smallest strategy that can honestly reach the quiz. Anything beyond that would be filler, and the real sacrifice is depth on mixed circuits and any topic the teacher may weight heavily but which I cannot verify.",
          "recommendedEffort": {
            "lowMinutes": 40,
            "likelyMinutes": 50,
            "highMinutes": 50
          },
          "phases": [
            {
              "localId": "core",
              "title": "Core circuit rules and series/parallel patterns",
              "outcome": "You can state and use Ohm's law, the current/voltage rules, and the series and parallel resistance patterns on teacher-style questions.",
              "effort": {
                "lowMinutes": 20,
                "likelyMinutes": 25,
                "highMinutes": 25
              },
              "readinessCriterion": "You solve at least three of four core questions correctly without notes."
            },
            {
              "localId": "apply",
