{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "Explain Bayes' rule, correctly solve a changed medical-test example, and diagnose why base rate and sensitivity are distinct, with remediation only if the check reveals confusion."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "MASTERY",
          "outcome": "Develop the ability to explain Bayes’ rule and apply it to a changed medical-test probability example, resolving the confusion between base rate and sensitivity.",
          "explanation": "The learner explicitly names a conceptual confusion: base rate versus sensitivity. The smallest useful path is an integrated worked explanation that confronts that distinction, followed by a changed transfer example. A separate contingent remediation activity is kept only if the transfer check shows the confusion persists. No extra practice quota or forced stages are added because the accepted outcome is explain-and-apply on a changed example, not broad fluency.",
          "recommendedEffort": {
            "lowMinutes": 40,
            "likelyMinutes": 65,
            "highMinutes": 90
          },
          "phases": [
            {
              "localId": "phase_1",
              "title": "Clarify base rate vs sensitivity through Bayes",
              "outcome": "A correct, explained solution to a medical-test Bayes problem that explicitly separates prevalence from sensitivity.",
              "effort": {
                "lowMinutes": 25,
                "likelyMinutes": 35,
                "highMinutes": 45
              },
              "readinessCriterion": "Learner explains in their own words why P(D) and P(+|D) are different quantities and uses both correctly in the calculation."
            },
            {
              "localId": "phase_2",
              "title": "Transfer to a changed example",
              "outcome": "Independent correct application and explanation on a new medical-test scenario with different numbers.",
              "effort": {
                "lowMinutes": 15,
                "likelyMinutes": 30,
                "highMinutes": 45
              },
              "readinessCriterion": "Correct posterior computed and explained without assistance on the changed example."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Provides the prevalence/base-rate concept that is the reported confusion source and is needed to compute the correct posterior."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The rule itself, which the learner must explain and apply to reach the accepted outcome."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "The changed-example requirement is the transfer evidence for mastery, not just repetition."
          }
        ],
        "activities": [
          {
            "localId": "explain_apply_bayes",
            "outcomeRefs": [
              "phase_1"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Explain and apply Bayes' rule to a medical-test example",
            "activityType": "Integrated explanation and worked application",
            "purpose": "Confront the base-rate/sensitivity confusion directly while producing a correct worked solution.",
            "instructions": "Work through this medical-test example. A disease has prevalence P(D)=0.01. A test has sensitivity P(+|D)=0.95 and false-positive rate P(+|no D)=0.10. 1) Write Bayes' rule in words and symbols. 2) State clearly what the base rate (prevalence) is and what the sensitivity is, and explain why they are different quantities. 3) Compute P(D|+) showing the numerator and denominator. 4) State the result and interpret it in one sentence. Use only the methods shown here; do not use odds/likelihood-ratio shortcuts unless you can derive them from Bayes' rule yourself.",
            "completionCriterion": "A written explanation of Bayes' rule plus a correct numerical posterior for the given example, with an explicit statement distinguishing base rate from sensitivity.",
            "effort": {
              "lowMinutes": 25,
              "likelyMinutes": 35,
              "highMinutes": 45
            },
            "timeboxMinutes": 40,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "transfer_changed_example",
            "outcomeRefs": [
              "phase_2"
            ],
            "scopeRefs": [
              "scope_3"
            ],
            "title": "Solve a changed medical-test example independently",
            "activityType": "Transfer application",
            "purpose": "Provide independent evidence of capability on an unfamiliar parameter set.",
            "instructions": "Create or use a new medical-test scenario with different numbers from the first activity (for example, prevalence 0.05, sensitivity 0.90, false-positive rate 0.20). Without looking back at the worked example, compute P(D|+), show the formula with the numbers substituted, and explain in your own words why the answer is or is not close to the sensitivity. If you cannot create your own numbers, use the example in this instruction. Do not use methods beyond Bayes' rule unless you can justify them from the rule.",
            "completionCriterion": "Correct posterior on the changed example, with formula substitution and an explanation that distinguishes prevalence from sensitivity.",
            "effort": {
              "lowMinutes": 15,
              "likelyMinutes": 30,
              "highMinutes": 45
            },
            "timeboxMinutes": 35,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [
              "explain_apply_bayes"
            ]
          },
          {
            "localId": "remediation_base_rate",
            "outcomeRefs": [],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Targeted remediation on base rate vs sensitivity",
            "activityType": "Conditional remediation",
            "purpose": "Address a concrete observed failure from the transfer check, if any.",
            "instructions": "If the transfer example showed the same base-rate/sensitivity confusion, re-derive Bayes' rule from the definition of conditional probability for one new simple example, explicitly labelling which quantity is the base rate and which is the sensitivity. Then redo the failed step of the transfer example. If the transfer example was correct, this activity is not needed.",
            "completionCriterion": "Correct re-derivation and corrected step on the previously failed example, or no action if the trigger condition did not occur.",
            "effort": {
              "lowMinutes": 10,
              "likelyMinutes": 20,
              "highMinutes": 30
            },
            "timeboxMinutes": 25,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "transfer_changed_example",
                "condition": "The transfer example contains an incorrect posterior or an explanation that still confuses base rate with sensitivity."
              }
            },
            "hardDependencies": [
              "transfer_changed_example"
            ]
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "No separate drill set is included because the accepted outcome is explanation plus one changed application; additional drills would add time without new evidence.",
            "Remediation is contingent rather than upfront to avoid unnecessary repetition if the transfer check is clean."
          ],
          "unresolvedUncertainty": [
            "The learner's current arithmetic fluency with conditional probability is unknown; the integrated activity will reveal whether arithmetic support is needed."
          ],
          "stoppingConditions": [
            "Stop when the changed example is solved correctly and explained, or when the contingent remediation resolves an observed failure."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The plan keeps only the two activities needed for the accepted outcome: an integrated explanation/application and a changed transfer example. A contingent remediation activity is included only if the transfer check reveals the named confusion. This avoids extra practice quotas while preserving the mastery requirement and the specific base-rate/sensitivity focus."
}

