{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "A working, independently demonstrated CSV totals report (plan_1) plus a working JSON expenses report (plan_2) that both reuse the same single loops/dictionaries prerequisite learned once."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Prepare a CSV totals report that reads expense data and prints per-category totals, using loops and dictionaries learned once.",
          "explanation": "The learner is new to loops and dictionaries, so the useful next checkpoint is a first working CSV totals report built on one shared prerequisite. The loops/dictionaries learning is owned once by plan_1 and reused by plan_2 through a root shared dependency rather than duplicated. Later CSV features (sorting, formatting, file output) stay strategic and unbooked.",
          "recommendedEffort": {
            "lowMinutes": 60,
            "likelyMinutes": 90,
            "highMinutes": 150
          },
          "phases": [
            {
              "localId": "loops_dicts",
              "title": "Loops and dictionaries prerequisite",
              "outcome": "Read a list of records with a loop and accumulate per-key totals in a dictionary.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 75
              },
              "readinessCriterion": "Can write a loop that builds a totals dictionary from a list of category/amount pairs without assistance."
            },
            {
              "localId": "csv_report",
              "title": "CSV totals report",
              "outcome": "Read CSV expense rows and print correct per-category totals.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 75
              },
              "readinessCriterion": "Produces a correct totals report from a provided CSV file."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Shared loops/dictionaries prerequisite, taught once here and reused by plan_2 via a root shared dependency."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The CSV totals report itself, the first useful checkpoint for plan_1."
          }
        ],
        "activities": [
          {
            "localId": "loops_dicts_practice",
            "outcomeRefs": [
              "loops_dicts"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Learn loops and dictionaries with a small totals exercise",
            "activityType": "guided practice",
            "purpose": "Build the single shared loops/dictionaries prerequisite that both reports depend on.",
            "instructions": "Create a list of (category, amount) pairs, e.g. [(\"food\", 12), (\"travel\", 30), (\"food\", 8)]. Write a for loop that walks the list and accumulates a running total per category into a dictionary. Print the dictionary. Then change the data to a new set of pairs and repeat, checking that each category total is correct. Work only with loops and dictionaries; no CSV or JSON yet.",
            "completionCriterion": "A loop correctly builds a totals dictionary from a list of category/amount pairs, verified against a hand-checked expected total for each category.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 75
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "csv_totals_report",
            "outcomeRefs": [
              "csv_report"
            ],
            "scopeRefs": [
              "scope_2"
            ],
            "title": "Build the CSV totals report",
            "activityType": "project task",
            "purpose": "Apply the shared loops/dictionaries prerequisite to produce the first working CSV totals report.",
            "instructions": "Create a CSV file with header category,amount and a few expense rows. Read the file, loop over the rows, and accumulate per-category totals in a dictionary. Print one line per category with its total. Hand-check the totals against the CSV. If you are unsure how to read a CSV file, use the simplest built-in approach and ask for help only on file reading, not on the loops/dictionaries logic you already practiced.",
            "completionCriterion": "Running the program on the CSV file prints correct per-category totals that match a hand-computed check.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 75
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [
              "loops_dicts_practice"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has no prior Python loops or dictionaries experience, as stated."
          ],
          "tradeOffs": [
            "Later CSV features such as sorting and file output are deferred to keep the first checkpoint small and achievable."
          ],
          "unresolvedUncertainty": [
            "Whether the learner will need extra support reading CSV files; this is handled inside the report activity rather than as a separate prerequisite."
          ],
          "stoppingConditions": [
            "Stop once the CSV totals report produces correct hand-checked totals."
          ]
        }
      }
    },
    {
      "planRef": "plan_2",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a JSON expenses report that reads expense data and prints per-category totals, reusing the shared loops/dictionaries prerequisite learned once in plan_1.",
          "explanation": "The loops/dictionaries prerequisite is owned by plan_1 and counted once; plan_2 depends on it through a root shared dependency rather than teaching it again. The useful next checkpoint for plan_2 is a working JSON expenses report. Further JSON features stay strategic and unbooked.",
          "recommendedEffort": {
            "lowMinutes": 30,
            "likelyMinutes": 45,
            "highMinutes": 75
          },
          "phases": [
            {
              "localId": "json_report",
              "title": "JSON expenses report",
              "outcome": "Read JSON expense records and print correct per-category totals.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 75
              },
              "readinessCriterion": "Produces a correct totals report from a provided JSON file."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Reuses the shared loops/dictionaries prerequisite owned by plan_1; no duplicate teaching here."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The JSON expenses report itself, the first useful checkpoint for plan_2."
          }
        ],
        "activities": [
          {
            "localId": "json_expenses_report",
            "outcomeRefs": [
              "json_report"
            ],
            "scopeRefs": [
              "scope_2"
            ],
            "title": "Build the JSON expenses report",
            "activityType": "project task",
            "purpose": "Apply the shared loops/dictionaries prerequisite to produce a first working JSON expenses report.",
            "instructions": "Create a JSON file containing a list of expense objects, each with a category and an amount, e.g. [{\"category\": \"food\", \"amount\": 12}, {\"category\": \"travel\", \"amount\": 30}]. Read the file, loop over the records, and accumulate per-category totals in a dictionary. Print one line per category with its total. Hand-check the totals against the JSON file. Reuse the loops/dictionaries logic you already practiced; do not re-learn it here.",
            "completionCriterion": "Running the program on the JSON file prints correct per-category totals that match a hand-computed check.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 75
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner will have completed the shared loops/dictionaries prerequisite in plan_1 before starting this report."
          ],
          "tradeOffs": [
            "Further JSON features such as nested structures and file output are deferred to keep the first checkpoint small."
          ],
          "unresolvedUncertainty": [
            "Whether the learner will need extra support reading JSON files; this is handled inside the report activity."
          ],
          "stoppingConditions": [
            "Stop once the JSON expenses report produces correct hand-checked totals."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [
    {
      "prerequisite": {
        "planRef": "plan_1",
        "activityId": "loops_dicts_practice"
      },
      "dependent": {
        "planRef": "plan_2",
        "activityId": "json_expenses_report"
      },
      "strength": "HARD",
      "reason": "The JSON expenses report requires the loops/dictionaries capability taught once in plan_1, so the shared prerequisite is owned there and counted once."
    }
  ],
  "tradeOffExplanation": "The loops/dictionaries prerequisite is taught once in plan_1 and reused by plan_2 through a hard shared dependency, avoiding duplicate prerequisite work. Both reports are kept as small, independently checkable first checkpoints, with later features deferred as strategic scope."
}

