        "schemaVersion": 2,
        "strategy": {
          "policy": "GENERAL",
          "outcome": "Complete a 45-minute uninterrupted authentic circuit lab check whose measurements require one continuous sitting; availability of 30 minutes per day cannot accommodate it, so the conflict is disclosed rather than silently shortened.",
          "explanation": "The accepted requirement is an indivisible 45-minute uninterrupted authentic lab check. Splitting it would invalidate the measurement, so no splitPoints or shorter substitute are offered. Daily capacity is 30 minutes, so this single COMMITTED activity honestly exceeds any available slot; retaining its true duration and indivisibility lets the allocator report the conflict instead of erasing required learning into a feasible empty plan. No preparatory or substitute activity is committed because none was accepted and none is needed to reach the check.",
          "recommendedEffort": {
            "lowMinutes": 45,
